_BASE_AGENT = _BASE_NS["agent"]
_PARENT_IMPL = _BASE_NS["_IMPL"]
_MARKET_PORTFOLIO = _PORTFOLIO_NS["market_portfolio"]
_MARKET_CONFIG = {'market_first_day': 6, 'market_shop_cycle_guard': True, 'market_sale_items': 'STRAWBERRY,WOOL,EGG,MELON,CARROT,TOMATO', 'market_max_items': 9, 'market_max_lookahead': 7, 'market_protect_first_sale': False}

def _selected_tape(observation):
    player = int(observation.get("player", 0))
    step = int(observation.get("step", 0))
    native = _PARENT_IMPL.chassis.players[player]
    route = 2 if step >= 648 else native.get("route", 0)
    return SimpleNamespace(
        route_id=f"local-best-native-{route}",
        actions=tuple(_PARENT_IMPL.chassis.routes[route]),
    )

def agent(observation, configuration=None):
    action = _BASE_AGENT(observation, configuration)
    try:
        standard = configuration is None or all(
            configuration.get(key, default) == default
            for key, default in (
                ("boardSize", 10), ("turnsPerDay", 24),
                ("shedCapacity", 100), ("maxMarketOrdersPerTurn", 10),
            )
        )
        if standard:
            action = _MARKET_PORTFOLIO(
                observation, action, _MARKET_CONFIG,
                _selected_tape(observation),
            )
    except Exception:
        pass
    return action
